const data = $input.first().json;
const topic         = (data['Topic or Industry'] || data.topic         || '').trim();
const keyword       = (data['Keyword']            || data.keyword       || '').trim();
const clientWebsite = (data['Client Website']     || data.clientWebsite || '').trim();
const audience      = (data['Audience']           || data.audience      || '').trim();
const providerRaw   = (data['AI Provider']        || data.provider      || 'Claude (Anthropic)').trim();
const provider = providerRaw.toLowerCase().includes('openai') ? 'openai' : 'anthropic';
if (!topic)   throw new Error('Topic or Industry is required');
if (!keyword) throw new Error('Keyword is required');
return [{ json: { topic, keyword, audience, clientWebsite, provider } }];

const { topic, keyword, audience, clientWebsite, provider } = $input.first().json;
const sources = [
  { source: 'Reddit',     query: `site:reddit.com "${topic}" "${keyword}" B2B OR software OR tool` },
  { source: 'G2',         query: `site:g2.com/reviews "${topic}" "${keyword}"` },
  { source: 'Capterra',   query: `site:capterra.com "${topic}" "${keyword}"` },
  { source: 'Trustpilot', query: `site:trustpilot.com "${topic}" "${keyword}"` },
  { source: 'Forum',      query: `"${topic}" "${keyword}" community OR forum questions pain points` },
];
return sources.map(s => ({ json: { ...s, topic, keyword, audience, clientWebsite, provider } }));

const allItems = $input.all();
const first = allItems[0].json;
const { topic, keyword, audience, clientWebsite, provider } = first;

// Aggregate snippets from all 5 Serper responses
const snippets = allItems.flatMap(item => {
  const source = item.json.source || 'Forum';
  return (item.json.organic || []).slice(0, 3).map(r => ({
    title: r.title || '',
    snippet: r.snippet || '',
    source,
  }));
}).slice(0, 15);

// Fetch client website — no API key needed, plain fetch is allowed in Code nodes
let websiteText = null;
if (clientWebsite) {
  try {
    const res = await fetch(clientWebsite, {
      headers: { 'User-Agent': 'Mozilla/5.0 (compatible; IntentSpymasterBot/1.0)', 'Accept': 'text/html' },
    });
    if (res.ok) {
      const html = await res.text();
      websiteText = html
        .replace(/<script[\s\S]*?<\/script>/gi, ' ')
        .replace(/<style[\s\S]*?<\/style>/gi, ' ')
        .replace(/<[^>]+>/g, ' ')
        .replace(/\s+/g, ' ')
        .trim()
        .slice(0, 3000);
    }
  } catch {}
}

return [{ json: { topic, keyword, audience, clientWebsite, provider, snippets, websiteText } }];

const { topic, keyword, audience, provider, snippets, websiteText } = $input.first().json;

const audienceClause = audience
  ? `
Audience filter: Focus signals relevant to "${audience}". Deprioritize signals not applicable to this persona.`
  : '';

const websiteSection = websiteText
  ? `

Client website copy (use this to understand who the client is and filter for relevant signals):
${websiteText}`
  : '';

const clientContextFormat = websiteText
  ? '{ "purpose": "1-2 sentences: what they do and what makes them unique", "personas": "1-2 sentences: who they serve", "problems": "1-2 sentences: pains they solve" }'
  : 'null';

const formattedSnippets = snippets
  .map((s, i) => `[${i + 1}] Source: ${s.source}
Title: ${s.title}
Snippet: ${s.snippet}`)
  .join('

');

const prompt = `You are a B2B content strategist and positioning analyst.${websiteSection}

Below are search result snippets about "${topic}" (keyword: "${keyword}"). Extract genuine user intent signals for B2B content creation.${audienceClause}

Rules:
- Only extract signals present in the snippets. Do not invent or infer beyond what is written.
- Focus on signals relevant to a B2B audience (buyers, practitioners, decision-makers).
- Skip consumer-only content, spam, or irrelevant results.
- If website copy was provided, deprioritise signals unrelated to what the client does.
- Write each signal as a clear, natural statement or question (1-2 sentences max).
- Return a maximum of 15 signals total.

Signal categories:
- Question — something users are actively trying to figure out
- Pain Point — a frustration, failure, or unmet need
- Comparison — evaluating options, switching decisions, or vendor comparisons
- Anecdote — a personal story or real-world use case
- Feature Request — something users wish a product or solution would do

Return ONLY a valid JSON object. No explanation, no markdown, no preamble.

Format:
{
  "clientContext": ${clientContextFormat},
  "signals": [
    { "signal": "...", "category": "Pain Point", "source": "Reddit" }
  ]
}
${websiteText ? '
For clientContext: be specific, avoid generic filler like 'we help businesses grow', 1-2 sentences per field.' : ''}

Snippets:
${formattedSnippets}`;

const aiBody = provider === 'openai'
  ? { model: 'gpt-4o', max_tokens: 1500, messages: [{ role: 'user', content: prompt }] }
  : { model: 'claude-sonnet-4-20250514', max_tokens: 1500, messages: [{ role: 'user', content: prompt }] };

return [{ json: { aiBody, topic, keyword, audience, provider, snippetCount: snippets.length } }];

const aiResponse = $input.first().json;

// Pull original context from the prompt-building node
const ctx = $node['Build Analysis Prompt'].json;
const { topic, keyword, provider, snippetCount } = ctx;

// Extract text from whichever provider responded
let rawText;
if (aiResponse.content && Array.isArray(aiResponse.content)) {
  rawText = aiResponse.content[0].text; // Anthropic
} else if (aiResponse.choices && Array.isArray(aiResponse.choices)) {
  rawText = aiResponse.choices[0].message.content; // OpenAI
} else {
  throw new Error('Unexpected AI response: ' + JSON.stringify(aiResponse).slice(0, 200));
}

const cleaned = rawText.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
const { clientContext, signals } = JSON.parse(cleaned);

return [{ json: { signals, clientContext, snippetCount, topic, keyword, provider } }];

const { signals, clientContext, snippetCount, topic, keyword, provider } = $input.first().json;

const CATEGORY_ORDER = ['Question', 'Pain Point', 'Comparison', 'Anecdote', 'Feature Request'];
const CATEGORY_COLORS = { 'Question': '#4f7ef8', 'Pain Point': '#e05c5c', 'Comparison': '#f0964a', 'Anecdote': '#7c5cbf', 'Feature Request': '#27ae7a' };
const SOURCE_COLORS = { 'Reddit': '#ff4500', 'G2': '#ff492c', 'Capterra': '#00a2e8', 'Trustpilot': '#00b67a', 'Forum': '#7c5cbf' };
const PROVIDER_LABELS = { anthropic: 'Claude', openai: 'ChatGPT' };

const grouped = {};
for (const cat of CATEGORY_ORDER) grouped[cat] = [];
for (const s of (signals || [])) {
  const cat = grouped[s.category] ? s.category : 'Question';
  grouped[cat].push(s);
}

function esc(str) {
  return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// ── HTML preview ─────────────────────────────────────────────────
let categoriesHtml = '';
for (const cat of CATEGORY_ORDER) {
  const items = grouped[cat];
  if (!items.length) continue;
  const color = CATEGORY_COLORS[cat] || '#888';
  const rows = items.map(s => {
    const srcColor = SOURCE_COLORS[s.source] || '#888';
    return `<li class='si'><span class='src' style='background:${srcColor}'>${esc(s.source)}</span><span class='st'>${esc(s.signal)}</span></li>`;
  }).join('');
  categoriesHtml += `<div class='cb' style='border-left-color:${color}'><h3 class='ch' style='color:${color}'>${esc(cat)} <span class='cn'>${items.length}</span></h3><ul class='sl'>${rows}</ul></div>`;
}

let clientHtml = '';
if (clientContext) {
  clientHtml = `<div class='cc'><p class='cl'>Client Understanding</p><div class='cr'><span class='ck'>Purpose</span><p>${esc(clientContext.purpose)}</p></div><div class='cr'><span class='ck'>Personas</span><p>${esc(clientContext.personas)}</p></div><div class='cr'><span class='ck'>Problems</span><p>${esc(clientContext.problems)}</p></div></div>`;
}

// ── Word document (MHTML format Word opens natively) ─────────────
const providerLabel = PROVIDER_LABELS[provider] || provider;
const safeFilename = topic.replace(/[^a-z0-9]/gi, '-').toLowerCase();

let wordSections = '';
if (clientContext) {
  wordSections += `<h2 style="color:#4f7ef8;font-family:Arial,sans-serif;font-size:14pt;margin-top:0">Client Understanding</h2>`;
  wordSections += `<p style="font-family:Arial,sans-serif;font-size:11pt;margin:4pt 0"><b>Purpose:</b> ${esc(clientContext.purpose || '')}</p>`;
  wordSections += `<p style="font-family:Arial,sans-serif;font-size:11pt;margin:4pt 0"><b>Personas:</b> ${esc(clientContext.personas || '')}</p>`;
  wordSections += `<p style="font-family:Arial,sans-serif;font-size:11pt;margin:4pt 0 14pt 0"><b>Problems:</b> ${esc(clientContext.problems || '')}</p>`;
}
for (const cat of CATEGORY_ORDER) {
  const items = grouped[cat];
  if (!items.length) continue;
  const color = CATEGORY_COLORS[cat] || '#888';
  wordSections += `<h2 style="color:${color};font-family:Arial,sans-serif;font-size:13pt;margin-top:16pt;margin-bottom:6pt;border-bottom:2px solid ${color};padding-bottom:4pt">${esc(cat)} <span style="font-weight:normal;font-size:10pt;color:#6b7280">(${items.length})</span></h2>`;
  for (const s of items) {
    wordSections += `<p style="font-family:Arial,sans-serif;font-size:11pt;margin:6pt 0 6pt 14pt;line-height:1.5"><b style="color:#374151">[${esc(s.source)}]</b> ${esc(s.signal)}</p>`;
  }
}

const wordDoc = `<html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'><head><meta charset='UTF-8'><title>${esc(topic)}</title><!--[if gte mso 9]><xml><w:WordDocument><w:View>Print</w:View><w:Zoom>100</w:Zoom><w:DoNotOptimizeForBrowser/></w:WordDocument></xml><![endif]--><style>@page{margin:2cm}body{font-family:Arial,sans-serif;font-size:11pt;color:#1a1a2e}h1{font-size:22pt;font-weight:bold;color:#1a1a2e;margin-bottom:4pt}p.meta{color:#6b7280;font-size:10pt;margin-top:0;margin-bottom:18pt;border-bottom:1px solid #e4e7ed;padding-bottom:10pt}p.footer{margin-top:28pt;color:#9ca3af;font-size:9pt}</style></head><body><h1>${esc(topic)}</h1><p class='meta'>${signals.length} signals &nbsp;|&nbsp; ${snippetCount} sources scanned &nbsp;|&nbsp; keyword: ${esc(keyword)} &nbsp;|&nbsp; via ${esc(providerLabel)}</p>${wordSections}<p class='footer'>Generated by Intent Spymaster &middot; Signals filtered to B2B relevance</p></body></html>`;

const wordBase64 = Buffer.from(wordDoc, 'utf8').toString('base64');
const downloadUri = `data:application/vnd.ms-word;base64,${wordBase64}`;

// ── Final HTML page ───────────────────────────────────────────────
const html = `<!DOCTYPE html><html lang='en'><head><meta charset='UTF-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Intent Signals — ${esc(topic)}</title><style>*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;background:#f8f9fb;color:#1a1a2e;padding:32px 16px 64px;line-height:1.5}.wrap{max-width:700px;margin:0 auto}.logo{font-size:12px;color:#9ca3af;letter-spacing:.06em;margin-bottom:10px}h1{font-size:22px;font-weight:800;margin-bottom:10px}.chips{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px}.chip{background:#fff;border:1px solid #e4e7ed;border-radius:20px;padding:3px 10px;font-size:12px;color:#6b7280}.dl-btn{display:inline-flex;align-items:center;gap:8px;background:#1a1a2e;color:#fff;border-radius:8px;padding:9px 18px;font-size:13px;font-weight:600;text-decoration:none;margin-bottom:24px;cursor:pointer}.dl-btn:hover{background:#2d2d4e}.cc{background:#fff;border:1px solid #e4e7ed;border-left:4px solid #4f7ef8;border-radius:10px;padding:16px 18px;margin-bottom:14px}.cl{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:#4f7ef8;margin-bottom:10px}.cr{margin-bottom:8px}.cr:last-child{margin-bottom:0}.ck{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:#9ca3af;display:block;margin-bottom:2px}.cr p{font-size:13px;line-height:1.5}.cb{background:#fff;border:1px solid #e4e7ed;border-left:4px solid #888;border-radius:10px;padding:16px 18px;margin-bottom:12px}.ch{font-size:14px;font-weight:700;margin-bottom:12px;display:flex;align-items:center;gap:8px}.cn{background:#f8f9fb;border:1px solid #e4e7ed;border-radius:12px;padding:1px 8px;font-size:12px;color:#6b7280;font-weight:400}.sl{list-style:none}.si{display:flex;align-items:flex-start;gap:10px;padding:9px 0;border-bottom:1px solid #f0f2f5}.si:last-child{border-bottom:none;padding-bottom:0}.src{flex-shrink:0;border-radius:4px;padding:2px 7px;font-size:10px;font-weight:700;color:#fff;margin-top:3px;white-space:nowrap}.st{font-size:13px;line-height:1.5}.foot{margin-top:28px;font-size:11px;color:#d1d5db;text-align:center}</style></head><body><div class='wrap'><p class='logo'>◈ INTENT SPYMASTER</p><h1>${esc(topic)}</h1><div class='chips'><span class='chip'>${signals.length} signals</span><span class='chip'>${snippetCount} sources scanned</span><span class='chip'>keyword: ${esc(keyword)}</span><span class='chip'>via ${esc(providerLabel)}</span></div><a class='dl-btn' href='${downloadUri}' download='intent-signals-${safeFilename}.doc'>&#11015; Download Word Doc</a>${clientHtml}${categoriesHtml}<p class='foot'>Generated by Intent Spymaster &middot; Signals filtered to B2B relevance</p></div></body></html>`;

return [{ json: { html } }];
